import { injectIntoGlobalHook } from "/@react-refresh";
injectIntoGlobalHook(window);
window.$RefreshReg$ = () => {};
window.$RefreshSig$ = () => (type) => type;

/* Splash screen styles -- inlined so they render before any JS loads. */
#splash {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  /* Transparent so macOS glass/vibrancy shows through. The native
     window chrome provides the visual backdrop. */
  background: transparent;
  transition: opacity 300ms ease-out;
  /* Allow dragging the window from the splash on macOS */
  -webkit-app-region: drag;
}
#splash.hiding {
  opacity: 0;
  pointer-events: none;
}
#splash svg {
  height: 20px;
  width: auto;
  color: hsl(var(--foreground, 0 0% 93%));
}
#splash .dots {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 24px;
}
#splash .dots span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: hsl(var(--muted-foreground, 0 0% 45%) / 0.4);
  animation: splash-pulse 1.2s ease-in-out infinite;
}
#splash .dots span:nth-child(2) { animation-delay: 150ms; }
#splash .dots span:nth-child(3) { animation-delay: 300ms; }
@keyframes splash-pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

